{"implementation":"def solve(case):
    nodes = {n['id']: n for n in case['nodes']}
    required_symbols = set(case['required_symbols'])
    children = {nid: [] for nid in nodes}
    for n in case['nodes']:
        pid = n.get('parent')
        if pid is not None:
            children[pid].append(n['id'])
    sorted_ids = sorted(nodes.keys(), key=lambda nid: (-nodes[nid]['depth'], nid))
    removed = []
    for nid in sorted_ids:
        node = nodes[nid]
        if not node['removable']:
            continue
        if node['symbol'] in required_symbols or nid == 'root':
            continue
        if any(cid not in removed for cid in children.get(nid, [])):
            continue
        removed.append(nid)
    retained = sorted([nid for nid in nodes if nid not in removed])
    return {'removed_node_ids': removed, 'retained_node_ids': retained}"}
